+// withVerboseLog wires p.Logger, the -v log, to a buffer it returns.
+func withVerboseLog(p *Params) *bytes.Buffer {
+	var out bytes.Buffer
+	p.Logger = slog.New(slog.NewJSONHandler(&out, nil))
+	return &out
+}
