+func eventError(t *testing.T, event map[string]any) string {
+	t.Helper()
+	msg, ok := event["error"].(string)
+	if !ok || msg == "" {
+		t.Fatalf("error = %v, want a non-empty string", event["error"])
+	}
+	return msg
