+			if limit, ok := githubBatchLimit(context.Background(), p); ok {
+				t.Fatalf("githubBatchLimit = (%d, true), want no preflight", limit)
+			}
+			if out.Len() != 0 {
+				t.Fatalf("a skipped preflight logged: %s", &out)
+			}
+		})
